-- Approved RAG research implementation. Data only; no DDL or archive writes.
begin isolation level serializable;
select pg_advisory_xact_lock(hashtext('academy-migrations'));
do $$ begin
 if (select max(version) from academy.schema_migrations) is distinct from 7 then raise exception 'Expected schema version 7'; end if;
 if (select count(*) from academy.entries e join academy.entry_categories c on c.entry_id=e.id where c.category_id='04' and e.slug in ('rag-fundamentals','llamaindex','haystack','ragflow','docling','unstructured','microsoft-graphrag','lightrag'))<>8 then raise exception 'Expected eight reviewed RAG entries'; end if;
 if exists(select 1 from academy.entries where slug in ('rag-fundamentals','llamaindex','haystack','ragflow','docling','unstructured','microsoft-graphrag','lightrag') and revision<>case when slug='llamaindex' then 2 else 1 end) then raise exception 'Reviewed entries changed; reconcile before applying'; end if;
 if exists(select 1 from academy.entry_releases r join academy.entries e on e.id=r.entry_id where e.slug in ('rag-fundamentals','llamaindex','haystack','ragflow','docling','unstructured','microsoft-graphrag','lightrag')) then raise exception 'Release data changed since review'; end if;
 if exists(select 1 from academy.entries where slug in ('dspy','txtai','pathway') or lower(name) in ('dspy','txtai','pathway')) then raise exception 'New RAG candidate already exists'; end if;
 if exists(select 1 from academy.repositories where url in ('https://github.com/stanfordnlp/dspy','https://github.com/neuml/txtai','https://github.com/pathwaycom/pathway')) then raise exception 'Candidate repository already represented'; end if;
 if (select count(*) from academy.category_guide_steps where category_id='04')<>4 then raise exception 'Guide changed since review'; end if;
end $$;
 select e.id,coalesce((select max(position)+1 from academy.entry_sources where entry_id=e.id),0),'https://dspy.ai/','DSPy — תיעוד רשמי','2026-11-02','תפקיד, ארכיטקטורה ושפות; יתרונות, חסרונות ודוגמאות הם ניתוח פדגוגי ולא Benchmark.' from academy.entries e where e.slug='dspy' and not exists(select 1 from academy.entry_sources where entry_id=e.id and source_url='https://dspy.ai/');
 select e.id,coalesce((select max(position)+1 from academy.entry_sources where entry_id=e.id),0),'https://github.com/stanfordnlp/dspy','DSPy — מאגר רשמי','2026-11-02','מימוש Python ופעילות הפרויקט.' from academy.entries e where e.slug='dspy' and not exists(select 1 from academy.entry_sources where entry_id=e.id and source_url='https://github.com/stanfordnlp/dspy');
 select e.id,coalesce((select max(position)+1 from academy.entry_sources where entry_id=e.id),0),'https://arxiv.org/abs/2310.03714','DSPy','2026-11-02','שנת פרסום מאמר DSPy באוקטובר 2023; אינה תאריך תחילת פרויקט DSP שקדם לו ב־2022 או תאריך יצירת המאגר.' from academy.entries e where e.slug='dspy' and not exists(select 1 from academy.entry_sources where entry_id=e.id and source_url='https://arxiv.org/abs/2310.03714');
 select e.id,coalesce((select max(position)+1 from academy.entry_sources where entry_id=e.id),0),'https://neuml.github.io/txtai/','txtai — תיעוד רשמי','2026-11-02','תפקיד, ארכיטקטורה ושפות; יתרונות, חסרונות ודוגמאות הם ניתוח פדגוגי ולא Benchmark.' from academy.entries e where e.slug='txtai' and not exists(select 1 from academy.entry_sources where entry_id=e.id and source_url='https://neuml.github.io/txtai/');
 select e.id,coalesce((select max(position)+1 from academy.entry_sources where entry_id=e.id),0),'https://neuml.github.io/txtai/api/','txtai — API ושפות לקוח','2026-11-02','ליבה Python לעומת bindings וצריכת HTTP; C# אינה ברשימה שנבדקה.' from academy.entries e where e.slug='txtai' and not exists(select 1 from academy.entry_sources where entry_id=e.id and source_url='https://neuml.github.io/txtai/api/');
 select e.id,coalesce((select max(position)+1 from academy.entry_sources where entry_id=e.id),0),'https://github.com/neuml/txtai','txtai — מאגר רשמי','2026-11-02','זהות ותחזוקת הפרויקט; רישיון Apache-2.0.' from academy.entries e where e.slug='txtai' and not exists(select 1 from academy.entry_sources where entry_id=e.id and source_url='https://github.com/neuml/txtai');
 select e.id,coalesce((select max(position)+1 from academy.entry_sources where entry_id=e.id),0),'https://pypi.org/project/txtai/1.0.0/','txtai','2026-11-02','פרסום חבילת txtai 1.0.0 ב־PyPI ב־11 באוגוסט 2020. זהו אירוע פרסום מתועד, לא תאריך יצירת המאגר או מדידת השימוש.' from academy.entries e where e.slug='txtai' and not exists(select 1 from academy.entry_sources where entry_id=e.id and source_url='https://pypi.org/project/txtai/1.0.0/');
 select e.id,coalesce((select max(position)+1 from academy.entry_sources where entry_id=e.id),0),'https://pathway.com/developers/user-guide/introduction/welcome/','Pathway — תיעוד רשמי','2026-11-02','תפקיד, ארכיטקטורה ושפות; יתרונות, חסרונות ודוגמאות הם ניתוח פדגוגי ולא Benchmark.' from academy.entries e where e.slug='pathway' and not exists(select 1 from academy.entry_sources where entry_id=e.id and source_url='https://pathway.com/developers/user-guide/introduction/welcome/');
 select e.id,coalesce((select max(position)+1 from academy.entry_sources where entry_id=e.id),0),'https://pathway.com/developers/user-guide/llm-xpack/overview/','Pathway — LLM xpack','2026-11-02','רכיבי הכנת מסמכים, אינדוקס ותהליכי מודלים.' from academy.entries e where e.slug='pathway' and not exists(select 1 from academy.entry_sources where entry_id=e.id and source_url='https://pathway.com/developers/user-guide/llm-xpack/overview/');
 select e.id,coalesce((select max(position)+1 from academy.entry_sources where entry_id=e.id),0),'https://github.com/pathwaycom/pathway/blob/main/LICENSE.txt','Pathway — רישיון BSL','2026-11-02','Source-available עם תנאים נוספים; אין לסמן MIT/Apache או להסיק חופש שימוש בלתי מוגבל.' from academy.entries e where e.slug='pathway' and not exists(select 1 from academy.entry_sources where entry_id=e.id and source_url='https://github.com/pathwaycom/pathway/blob/main/LICENSE.txt');
 select e.id,coalesce((select max(position)+1 from academy.entry_sources where entry_id=e.id),0),'https://github.com/pathwaycom/serviette','Serviette — שרת RAG על Pathway','2026-11-02','llm-app מפנה כיום ל־Serviette; שרת נפרד באותו אקוסיסטם, ולא שם נוסף לליבת Pathway.' from academy.entries e where e.slug='pathway' and not exists(select 1 from academy.entry_sources where entry_id=e.id and source_url='https://github.com/pathwaycom/serviette');
 select e.id,coalesce((select max(position)+1 from academy.entry_sources where entry_id=e.id),0),'https://pathway.com/framework/blog/pathway-open-beta-announced/','Pathway','2026-11-02','הכרזת Open Beta של Pathway ב־5 בדצמבר 2022. אינה מועד הופעת יכולות RAG או פתיחת קוד מאוחרת יותר; אין להחליף אותה בשנת הקמת החברה.' from academy.entries e where e.slug='pathway' and not exists(select 1 from academy.entry_sources where entry_id=e.id and source_url='https://pathway.com/framework/blog/pathway-open-beta-announced/');
update academy.entries set revision=revision+1,verified_at='2026-11-02',revision_note='תיקון מחקר שאושר ב־2026-11-02: מקורות, אירועי פרסום, הבחנת שפות ומצב תחזוקה; הסיווג והפרסום נשמרו.' where slug='rag-fundamentals';
 select e.id,coalesce((select max(position)+1 from academy.entry_sources where entry_id=e.id),0),'https://learn.microsoft.com/en-us/dotnet/ai/conceptual/rag','Microsoft Learn — RAG ב־.NET','2026-11-02','תהליך הכנת מידע, שליפה ושמירת metadata למקורות.' from academy.entries e where e.slug='rag-fundamentals' and not exists(select 1 from academy.entry_sources where entry_id=e.id and source_url='https://learn.microsoft.com/en-us/dotnet/ai/conceptual/rag');
update academy.entries set revision=revision+1,verified_at='2026-11-02',revision_note='תיקון מחקר שאושר ב־2026-11-02: מקורות, אירועי פרסום, הבחנת שפות ומצב תחזוקה; הסיווג והפרסום נשמרו.' where slug='llamaindex';
update academy.entry_lessons set language_support_note='מימוש Python הוא מסלול הלימוד הפעיל ברשומה. LlamaIndex.TS היה מימוש TypeScript רשמי, אך המאגר מסומן Deprecated ואינו מתוחזק; דפי תיעוד שעדיין זמינים אינם הוכחה לתמיכה פעילה. לא אומת SDK ליבה ל־C#/.NET; אפשר לשלב שירות או API נפרד.' where entry_id='llamaindex';
update academy.catalog_facts set language_support_summary='מימוש Python הוא מסלול הלימוד הפעיל ברשומה. LlamaIndex.TS היה מימוש TypeScript רשמי, אך המאגר מסומן Deprecated ואינו מתוחזק; דפי תיעוד שעדיין זמינים אינם הוכחה לתמיכה פעילה. לא אומת SDK ליבה ל־C#/.NET; אפשר לשלב שירות או API נפרד.',reviewed_at='2026-11-02' where entry_id='llamaindex';
delete from academy.entry_language_labels where entry_id='llamaindex';
 select e.id,coalesce((select max(position)+1 from academy.entry_sources where entry_id=e.id),0),'https://github.com/run-llama/LlamaIndexTS','LlamaIndex.TS — הודעת Deprecated','2026-11-02','מימוש TypeScript היסטורי, מאורכב ואינו מתוחזק; אין סימון Legacy כולל ל־Python.' from academy.entries e where e.slug='llamaindex' and not exists(select 1 from academy.entry_sources where entry_id=e.id and source_url='https://github.com/run-llama/LlamaIndexTS');
 select e.id,coalesce((select max(position)+1 from academy.entry_sources where entry_id=e.id),0),'https://www.llamaindex.ai/blog/llamaindex-is-more-than-a-rag-framework','llamaindex — אירוע פרסום מתועד','2026-11-02','הספק מתאר השקת מסגרת קוד פתוח בסוף 2022. דיוק שנה בלבד; אינה שנת השקה של LlamaCloud או מימוש TypeScript.' from academy.entries e where e.slug='llamaindex' and not exists(select 1 from academy.entry_sources where entry_id=e.id and source_url='https://www.llamaindex.ai/blog/llamaindex-is-more-than-a-rag-framework');
update academy.entries set revision=revision+1,verified_at='2026-11-02',revision_note='תיקון מחקר שאושר ב־2026-11-02: מקורות, אירועי פרסום, הבחנת שפות ומצב תחזוקה; הסיווג והפרסום נשמרו.' where slug='haystack';
 select e.id,coalesce((select max(position)+1 from academy.entry_sources where entry_id=e.id),0),'https://haystack.deepset.ai/blog/haystack-2-release/','Haystack — גרסאות והשקה רשמית','2026-11-02','הבחנה בין היסטוריית חבילות, הצגת השקה ב־2020 וגרסה נוכחית.' from academy.entries e where e.slug='haystack' and not exists(select 1 from academy.entry_sources where entry_id=e.id and source_url='https://haystack.deepset.ai/blog/haystack-2-release/');
 select e.id,coalesce((select max(position)+1 from academy.entry_sources where entry_id=e.id),0),'https://pypi.org/project/farm-haystack/0.1.0.post2/','haystack — אירוע פרסום מתועד','2026-11-02','פרסום חבילת farm-haystack 0.1.0.post2 ב־28 בנובמבר 2019. הספק מתאר השקה רשמית ב־2020; אין לבלבל עם Haystack 2 או 3. החבילה ההיסטורית ארכיונית, לא הפרויקט כולו.' from academy.entries e where e.slug='haystack' and not exists(select 1 from academy.entry_sources where entry_id=e.id and source_url='https://pypi.org/project/farm-haystack/0.1.0.post2/');
update academy.entries set revision=revision+1,verified_at='2026-11-02',revision_note='תיקון מחקר שאושר ב־2026-11-02: מקורות, אירועי פרסום, הבחנת שפות ומצב תחזוקה; הסיווג והפרסום נשמרו.',summary='מערכת RAG משולבת לעיבוד מסמכים, ניהול ידע ושליפה. בגרסת 1.0 RC שנבדקה קיימת ליבת שרת Go; יש להפריד בין מימוש השרת, SDK ולקוחות API, ולא לתאר את המערכת כ־backend Python בלבד.' where slug='ragflow';
update academy.entry_lessons set language_support_note='הליבה הנוכחית בענף main ובסדרת 1.0 RC שנבדקה כוללת שרתי Go; Python SDK וצריכת HTTP הם שכבות נפרדות. C#/.NET יכול לצרוך API מאומת; לא אומת SDK ליבה מקומי ל־.NET. תיאור גרסה ישנה ב־Python אינו תיאור אוטומטי של גרסת RC נוכחית.' where entry_id='ragflow';
update academy.catalog_facts set language_support_summary='הליבה הנוכחית בענף main ובסדרת 1.0 RC שנבדקה כוללת שרתי Go; Python SDK וצריכת HTTP הם שכבות נפרדות. C#/.NET יכול לצרוך API מאומת; לא אומת SDK ליבה מקומי ל־.NET. תיאור גרסה ישנה ב־Python אינו תיאור אוטומטי של גרסת RC נוכחית.',reviewed_at='2026-11-02' where entry_id='ragflow';
delete from academy.entry_language_labels where entry_id='ragflow';
