 select e.id,coalesce((select max(position)+1 from academy.entry_sources where entry_id=e.id),0),'https://github.com/infiniflow/ragflow/releases/tag/v0.1.0','ragflow — אירוע פרסום מתועד','2026-11-02','פרסום GitHub Release v0.1.0 ב־15 באפריל 2024; אירוע מתועד ולא טענה שזה היום הראשון לפרויקט או תאריך גרסת 1.0.' from academy.entries e where e.slug='ragflow' and not exists(select 1 from academy.entry_sources where entry_id=e.id and source_url='https://github.com/infiniflow/ragflow/releases/tag/v0.1.0');
update academy.entries set revision=revision+1,verified_at='2026-11-02',revision_note='תיקון מחקר שאושר ב־2026-11-02: מקורות, אירועי פרסום, הבחנת שפות ומצב תחזוקה; הסיווג והפרסום נשמרו.' where slug='docling';
