 select e.id,coalesce((select max(position)+1 from academy.entry_sources where entry_id=e.id),0),'https://www.microsoft.com/en-us/research/project/graphrag/','microsoft-graphrag — אירוע פרסום מתועד','2026-11-02','הכרזת Microsoft על פרסום הכלי ב־GitHub ב־2 ביולי 2024; נפרדת ממאמר מחקר או מפרסום מוקדם של הרעיון.' from academy.entries e where e.slug='microsoft-graphrag' and not exists(select 1 from academy.entry_sources where entry_id=e.id and source_url='https://www.microsoft.com/en-us/research/project/graphrag/');
