 select e.id,coalesce((select max(position)+1 from academy.entry_sources where entry_id=e.id),0),'https://github.com/HKUDS/RAG-Anything','RAG-Anything — קשר ל־LightRAG','2026-11-02','קשר בין הפרויקטים; נשאר מועמד להמשך ואינו רשומה חדשה כעת.' from academy.entries e where e.slug='lightrag' and not exists(select 1 from academy.entry_sources where entry_id=e.id and source_url='https://github.com/HKUDS/RAG-Anything');
