update academy.category_guides set introduction='מתחילים ביסודות וב־baseline, בודקים הכנת מסמכים ושליפה, ואז בוחנים שיפור מדיד ועדכון מקורות. DSPy, txtai ו־Pathway מכסות תפקידים שונים; אין חובה לאמץ את כולן.',note='הסיווגים המקוריים נשמרו. Python, לקוחות HTTP ומימושים היסטוריים מופרדים; LlamaIndex.TS אינה תמיכה פעילה. מסדי מידע וקטוריים ב־05 והערכה ב־10, עם קישורים לכלים קיימים במקום כפילות.' where category_id='04';
update academy.category_guide_steps set entry_id='dspy',instruction='אחרי baseline מגדירים מדד ודוגמאות ובוחנים שיפור באמצעות DSPy.',link_label='לתכנות ואופטימיזציה של תהליכים' where category_id='04' and position=3;
do $$ begin
 if (select count(*) from academy.entries e join academy.entry_categories c on c.entry_id=e.id where c.category_id='04')<>11 then raise exception 'Expected eleven RAG entries'; end if;
 if (select count(*) from academy.entries where slug in ('rag-fundamentals','llamaindex','haystack','ragflow','docling','unstructured','microsoft-graphrag','lightrag') and revision=case when slug='llamaindex' then 3 else 2 end)<>8 then raise exception 'Corrections incomplete'; end if;
end $$;
commit;
