insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('dspy','dspy','DSPy','framework','מסגרת Python לתכנות תהליכי מודלים מודולריים ולאופטימיזציה שלהם מול דוגמאות ומדד איכות. מתאימה לשיפור RAG, סיווג ותהליכי מודלים; אינה מערכת מוכנה לניהול מסמכים או מסד וקטורי.','published','verified','2026-11-02',1,'יישום מחקר שאושר ב־2026-11-02. דוגמאות ותרגילים פדגוגיים שלא הורצו; מדידות GitHub מצילום המחקר המקורי, לא מאיסוף חוזר.','2026-11-02','approved_proposal','2026-11-02','2026-11-02','User approved RAG research 2026-11-02: DSPy, txtai, Pathway and eight corrections; docs/DECISIONS.md D-031');
insert into academy.entry_categories (entry_id,category_id,position) values ('dspy','04',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('dspy','היכרות עם REST/JSON, SQL, יסודות RAG, הרשאות והערכת תשובות.','דוגמה לימודית מוצעת, שלא הורצה: צוות .NET מגדיר שאלות על נהלים ותשובות עם מקורות. שירות Python משפר את שלב ניסוח התשובה באמצעות DSPy, ו־ASP.NET Core ממשיך לאכוף הרשאות, לאמת JSON ולמדוד על סט בדיקה שלא השתתף בשיפור.','הגדירו מדד שמשלב נכונות תשובה וראיות מקור. תכננו חלוקת דוגמאות לכוונון ולבדיקה ומדידת עלות; השוו תהליך ידני לאופטימיזציה בלי להשתמש בשאלות הבדיקה לשיפור.','הליבה הרשמית שנבדקה היא Python. לא אומת SDK ליבה רשמי ב־C#/.NET. אפשר לתכנן שירות Python ולצרוך אותו ב־HTTP מ־ASP.NET Core; זו אינטגרציה בין שירותים, לא תמיכת .NET מקומית.','LlamaIndex ו־Haystack לתזמור ושליפה; DSPy לשיפור תוכנית המודלים על בסיס מדד. אלה תפקידים שיכולים להשתלב. אין הבטחת שיפור אוטומטית בכל אוסף.');
insert into academy.entry_sections (entry_id,position,title,body) values ('dspy',0,'איזו בעיה היא פותרת?','DSPy מאפשרת להגדיר משימות וזרימת מודלים בקוד ולשפר אותן מול מדד. היא מועילה כששינויי Prompt ידניים אינם תהליך אמין או שנדרש לשפר כמה שלבים יחד.');
insert into academy.entry_sections (entry_id,position,title,body) values ('dspy',1,'איך בנוי התהליך?','Signatures מגדירות קלט ופלט, Modules מרכיבים התנהגות, ו־Optimizers משתמשים בדוגמאות ובמדד שהוגדר. תהליך RAG יכול לשלב מאחזר חיצוני; DSPy אינה מחליפה את אחסון המסמכים או את בקרת ההרשאות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('dspy',2,'שימושים מרכזיים','שיפור שאלות ותשובות עם שליפה, סיווג וחילוץ מידע. מפרידים בין נתוני כוונון לנתוני בדיקה; ציון טוב על דוגמאות האופטימיזציה אינו מוכיח הכללה למידע חדש.');
insert into academy.entry_sections (entry_id,position,title,body) values ('dspy',3,'יתרונות, חסרונות וחלופות','היתרון הוא תהליך שיפור מודולרי ומדיד. המחיר הוא הכנת דוגמאות ומדד טוב ועלות קריאות מודל. Haystack ו־LlamaIndex יכולות להרכיב את תהליך השליפה, ו־DSPy יכולה להשתלב בהן; baseline ידני הוא כלי השוואה, לא יריב שחייב להפסיד.');
insert into academy.entry_sections (entry_id,position,title,body) values ('dspy',4,'תחזוקה ובטיחות','בצילום המחקר המאגר אינו ארכיוני וכולל פעילות מ־02/11/2026; זה אינו SLA. שמרו נתוני בדיקה בנפרד, הגנו על מידע רגיש שמועבר למודל ובדקו עלות לפני אופטימיזציה רחבה.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('dspy','should_know','כדאי להכיר בעדיפות גבוהה אחרי יסודות RAG והערכה: לעבור משינוי Prompt ידני לתהליך שיפור שנמדד על דוגמאות.','2026-11-02','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('dspy','מסגרת Python לתכנות ואופטימיזציה של תהליכי מודלים ו־RAG מול דוגמאות ומדד איכות.','הליבה הרשמית שנבדקה היא Python. לא אומת SDK ליבה רשמי ב־C#/.NET. אפשר לתכנן שירות Python ולצרוך אותו ב־HTTP מ־ASP.NET Core; זו אינטגרציה בין שירותים, לא תמיכת .NET מקומית.','verified','המאגר הרשמי הראשי בלבד. מדידות מצילום המחקר המאושר מ־2026-11-02; אינן דירוג איכות.','2026-11-02');
