insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('txtai','txtai','txtai','framework','מסגרת Python משולבת לחיפוש סמנטי, אינדקסים דלילים וצפופים, שאילתות SQL ותהליכי מודלים. מספקת גישה נוספת לבניית חיפוש ו־RAG דרך חבילה משולבת, עם API ושכבות קישור לשפות נוספות.','published','verified','2026-11-02',1,'יישום מחקר שאושר ב־2026-11-02. דוגמאות ותרגילים פדגוגיים שלא הורצו; מדידות GitHub מצילום המחקר המקורי, לא מאיסוף חוזר.','2026-11-02','approved_proposal','2026-11-02','2026-11-02','User approved RAG research 2026-11-02: DSPy, txtai, Pathway and eight corrections; docs/DECISIONS.md D-031');
insert into academy.entry_categories (entry_id,category_id,position) values ('txtai','04',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('txtai','היכרות עם REST/JSON, SQL, יסודות RAG, הרשאות והערכת תשובות.','דוגמה לימודית מוצעת: שירות txtai מאנדקס נהלים סינתטיים ומחזיר מקטעים עם מזהי מקור. שרת C# שולח שאילתת HTTP אחרי בדיקת הרשאות, בודק שהמסמכים מותרים ורק אז בונה בקשת מודל לתשובה.','השוו שליפה סמנטית ושליפה עם סינון metadata על אותו אוסף. תכננו מה קורה במסמך שנמחק ובשתי בקשות של ארגונים שונים.','הליבה היא Python. התיעוד הרשמי מציג bindings ל־API ב־Python, JavaScript, Java, Rust ו־Go; אלה לקוחות API, לא מימושי ליבה בכל שפה. C#/.NET אינה ברשימה שנבדקה ויכולה לצרוך HTTP; לא אומת SDK ליבה רשמי ל־.NET.','Haystack ו־LlamaIndex הן חלופות לתהליך RAG בקוד. מנוע חיפוש נפרד עם לוגיקת C# הוא baseline נוסף; מספר הרכיבים לבדו אינו מדד לאיכות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('txtai',0,'איזו בעיה היא פותרת?','txtai מרכזת חיפוש, אינדוקס ותהליכי מודלים במערכת Python. שימושים מרכזיים הם חיפוש ידע, סיווג תוכן ו־RAG, בלי להניח שכל פרויקט צריך מערך שירותים גדול.');
insert into academy.entry_sections (entry_id,position,title,body) values ('txtai',1,'איך בנויה המערכת?','האינדקס משלב יכולות חיפוש וייצוגי מידע עם שאילתות, ואפשר להרכיב Pipelines ו־Workflows. API אופציונלי חושף יכולות לצרכנים אחרים. יש להבדיל בין שירות Python לבין היישום שצורך אותו.');
insert into academy.entry_sections (entry_id,position,title,body) values ('txtai',2,'שימושים מרכזיים','חיפוש מסמכים לפי משמעות לצד סינון ושאילתות, ושימוש בתוצאות כידע למודל. מפתח SQL יכול ללמוד דרך ההשוואה בין שאילתה מובנית, ציון דמיון והקשר שמועבר למודל.');
insert into academy.entry_sections (entry_id,position,title,body) values ('txtai',3,'יתרונות, חסרונות וחלופות','היתרון הוא חבילה משולבת שקל יחסית לבחון על אותו תרחיש. צריך לבדוק גודל מידע, זיכרון, אחסון ותפעול; אין להניח שהיא מחליפה כל מנוע חיפוש ייעודי. השוו ל־Haystack ול־LlamaIndex או לפתרון חיפוש עם שכבת יישום עצמאית.');
insert into academy.entry_sections (entry_id,position,title,body) values ('txtai',4,'תחזוקה ובטיחות','רישיון הליבה Apache-2.0; צילום המחקר מציג פעילות מ־01/11/2026 ללא ארכוב. יש להגן על API שמאפשר אינדוקס ושינוי מסמכים, ולא להסתפק בהסתרת כפתורי עריכה בלקוח.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('txtai','should_know','כדאי להכיר כחלופה משולבת לחיפוש ו־RAG, ובמיוחד כדי להשוות חיבור בין SQL, אינדקס סמנטי ותהליך מודלים.','2026-11-02','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('txtai','מסגרת Python משולבת לחיפוש סמנטי, שאילתות SQL ותהליכי מודלים ושליפה מבוססת ידע.','הליבה היא Python. התיעוד הרשמי מציג bindings ל־API ב־Python, JavaScript, Java, Rust ו־Go; אלה לקוחות API, לא מימושי ליבה בכל שפה. C#/.NET אינה ברשימה שנבדקה ויכולה לצרוך HTTP; לא אומת SDK ליבה רשמי ל־.NET.','verified','המאגר הרשמי הראשי בלבד. מדידות מצילום המחקר המאושר מ־2026-11-02; אינן דירוג איכות.','2026-11-02');
