insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('pathway','pathway','Pathway','framework','מסגרת עיבוד נתונים עם API ב־Python ומנוע Rust לחישוב אינקרמנטלי. רלוונטית ל־RAG על מידע משתנה: עדכונים במקור יכולים להזין חישוב ואינדקס מתמשכים, במקום להסתמך רק על אינדוקס חד־פעמי.','published','verified','2026-11-02',1,'יישום מחקר שאושר ב־2026-11-02. דוגמאות ותרגילים פדגוגיים שלא הורצו; מדידות GitHub מצילום המחקר המקורי, לא מאיסוף חוזר.','2026-11-02','approved_proposal','2026-11-02','2026-11-02','User approved RAG research 2026-11-02: DSPy, txtai, Pathway and eight corrections; docs/DECISIONS.md D-031');
insert into academy.entry_categories (entry_id,category_id,position) values ('pathway','04',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('pathway','היכרות עם REST/JSON, SQL, יסודות RAG, הרשאות והערכת תשובות.','תרחיש לימודי מוצע: שינוי נוהל במקור מפעיל עדכון של תוצרי RAG. יישום ASP.NET Core מאמת משתמש ומחזיר תשובה מהגרסה המורשית. המדידה בודקת כמה זמן עובר משינוי המקור עד שהתשובה וההפניות משקפות אותו.','תכננו ניסוי עם הוספה, עריכה ומחיקת מסמך, כולל כשל באמצע העיבוד. השוו Pipeline מתמשך למשימה מחזורית ובדקו עלות, רעננות ותקינות הרשאות.','API הפיתוח הוא Python ומנוע הביצוע Rust. אין להסיק מכך API משתמש מלא ב־Rust. לא אומת SDK ליבה ל־C#/.NET; שירות נתונים או RAG יכול להיות נצרך דרך HTTP מ־.NET.','אינדוקס מחזורי ב־Haystack/LlamaIndex או Worker עצמאי ב־C# עשויים להספיק. Serviette מספקת שכבת שרת נוספת מעל Pathway, ולא מסגרת בלתי קשורה. יש לבדוק תנאי רישוי לפני שימוש.');
insert into academy.entry_sections (entry_id,position,title,body) values ('pathway',0,'איזו בעיה היא פותרת?','ידע ארגוני משתנה: מסמך נערך, רשומה מתווספת או מקור נמחק. Pathway מיועדת לעיבוד נתונים מתמשך ואינקרמנטלי, עם שימושים גם ב־ETL, אנליטיקה ו־RAG.');
insert into academy.entry_sections (entry_id,position,title,body) values ('pathway',1,'איך בנוי התהליך?','כותבים Pipeline ב־Python, והמנוע מבצע חישובים אינקרמנטליים. מחברים קוראים מקורות, טרנספורמציות מכינות מידע ותוצרים מזינים שליפה או צרכנים אחרים. שינוי מסמך צריך להשפיע גם על תוצרים נגזרים ולא רק על הקובץ המקורי.');
insert into academy.entry_sections (entry_id,position,title,body) values ('pathway',2,'שימושים וחלופות','מתאים לבחינת מערכות ידע על מקורות משתנים. האלטרנטיבה היא לעיתים אינדוקס תקופתי ב־LlamaIndex או Haystack, או Worker עצמאי. היתרון הוא מודל עדכונים מפורש; החיסרון הוא עוד תהליך מתמשך, מצב ומשאבים לתפעול.');
insert into academy.entry_sections (entry_id,position,title,body) values ('pathway',3,'רישיון ומוצרים קשורים','ליבת Pathway משתמשת ברישיון BSL עם תנאים נוספים; אין לתאר אותה כרישיון מתירני רגיל. Serviette היא שרת RAG מבוסס Pathway, והכתובת הישנה llm-app מפנה אליה. רשומה זו אינה מאחדת את מספרי Stars של שני המאגרים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('pathway',4,'תחזוקה ובטיחות','צילום המחקר מציג פעילות מ־30/10/2026 ללא ארכוב. בדקו הרשאות מקור, מחיקות, תקלות וחידוש עבודה, וזמן עד שהעדכון זמין לשליפה. הבטחת רעננות חייבת להימדד בתרחיש שלכם, ולא להיגזר מעצם בחירת המסגרת.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('pathway','should_know','כדאי להכיר כאשר ידע מתעדכן ברציפות; העמקה לפי צורך בעדכניות ולא כברירת מחדל לכל מאגר מסמכים קטן.','2026-11-02','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('pathway','מסגרת Python לעיבוד אינקרמנטלי ועדכון מידע ואינדקסי RAG מול מקורות שמשתנים לאורך זמן.','API הפיתוח הוא Python ומנוע הביצוע Rust. אין להסיק מכך API משתמש מלא ב־Rust. לא אומת SDK ליבה ל־C#/.NET; שירות נתונים או RAG יכול להיות נצרך דרך HTTP מ־.NET.','verified','המאגר הרשמי הראשי בלבד. מדידות מצילום המחקר המאושר מ־2026-11-02; אינן דירוג איכות.','2026-11-02');
