insert into academy.entry_sections(entry_id,position,title,body) select 'rag-fundamentals',coalesce(max(position)+1,0),'מימוש .NET והערכת המערכת','אפשר לבנות RAG ב־C#/.NET בלי להוסיף שירות Python. בוחרים מאחזר, מודל וחוזי API, משמרים מזהי מקור ובודקים הרשאות, מחיקה ונאמנות תשובה. DSPy משפרת תוכניות מול מדד, txtai משלבת חיפוש ו־Pathway עוסקת בעדכונים; אין הכרח להשתמש בכולן יחד.' from academy.entry_sections where entry_id='rag-fundamentals';
