insert into academy.entry_sections(entry_id,position,title,body) select 'llamaindex',coalesce(max(position)+1,0),'מצב שפות ותחזוקה לפי מימוש','Python אינה מסומנת Legacy. דווקא מאגר LlamaIndex.TS הועבר לארכיון באפריל 2026 וה־README מציין הפסקת תחזוקה. אין להסיק שתמיכת LlamaCloud/LlamaParse בלקוחות שונים היא אותה מסגרת TypeScript ישנה, ואין לחבר Stars משני המאגרים.' from academy.entry_sections where entry_id='llamaindex';
