insert into academy.entry_sections(entry_id,position,title,body) select 'haystack',coalesce(max(position)+1,0),'גרסאות והיסטוריית פרסום','נשמרת שנת 2019 לפי חבילת farm-haystack מתועדת, ולא כתאריך השקה של הגרסה הנוכחית. הספק מתאר השקה ב־2020; חבילת farm-haystack הישנה ארכיונית, אך אין להסיק מכך שהפרויקט הנוכחי Haystack אינו מתוחזק. בדוגמאות יש לבחור תיעוד וגרסה תואמים.' from academy.entry_sections where entry_id='haystack';
