insert into academy.entry_sections(entry_id,position,title,body) select 'ragflow',coalesce(max(position)+1,0),'גרסה, ליבה ולקוחות','המאגר הנוכחי כולל go.mod והנחיות בניית שרת Go. ה־Release שנבדק הוא v1.0.0-rc3 ולא גרסה יציבה שהובטחה כאן. יש לבחור גרסה ותיעוד יחד ולהבחין בין קוד שרת, SDK Python, API וממשק משתמש.' from academy.entry_sections where entry_id='ragflow';
