insert into academy.entry_sections(entry_id,position,title,body) select 'docling',coalesce(max(position)+1,0),'סוג הכלי והפרדת אחריות','Docling היא ספריית הכנת מסמכים: המרה, מבנה ו־chunking. היא מוצגת בסיווג sdk הקיים, אך אינה מערכת RAG מלאה. פרסום הקוד ביולי 2024 נפרד מדוח המחקר או מהכרזה מאוחרת; אין הבטחת דיוק OCR בעברית בלי בדיקה על דוגמאות.' from academy.entry_sections where entry_id='docling';
