insert into academy.entry_sections(entry_id,position,title,body) select 'unstructured',coalesce(max(position)+1,0),'פרסום הספרייה וגבולות המוצר','חבילת פיתוח מתועדת מ־2022 אינה הוכחה לזמינות כל תכונות השירות המסחרי באותה שנה או בספרייה. סיווג sdk כאן מתייחס לספריית הכנת מסמכים ולא למערכת RAG מלאה; יש להבחין בין רישיון הספרייה, API ומוצר מנוהל.' from academy.entry_sections where entry_id='unstructured';
