insert into academy.entry_sections(entry_id,position,title,body) select 'microsoft-graphrag',coalesce(max(position)+1,0),'שם הגישה לעומת המימוש','GraphRAG היא גם שם למשפחת גישות. רשומה זו מתייחסת למימוש Microsoft המסוים ולמקורותיו, ולא לכל פתרון עם גרף. Python היא שפת המימוש שנבדק; המותג Microsoft אינו הוכחה ל־SDK C# מקומי.' from academy.entry_sections where entry_id='microsoft-graphrag';
