insert into academy.entry_sections(entry_id,position,title,body) select 'lightrag',coalesce(max(position)+1,0),'קשר ל־RAG-Anything ומדידה','RAG-Anything מרחיבה תהליכי RAG רב־מודליים ומשתלבת ב־LightRAG לפי תיעוד הפרויקט. היא אינה נוספה כרשומה במסגרת אישור זה. Stars ותאריך Commit שייכים למאגר LightRAG בלבד, ואינם מדד הצלחת שליפה או סכום של פרויקטים קשורים.' from academy.entry_sections where entry_id='lightrag';
